@startuml BP02_Internal_Transfer

title BP-02 - Quy trình Điều chuyển hàng giữa các kho

scale 2000 width

!pragma useVerticalIf on

skinparam backgroundColor #FFFFFF
skinparam defaultFontName Arial
skinparam defaultFontSize 14
skinparam shadowing false
skinparam roundcorner 8
skinparam wrapWidth 250
skinparam swimlaneWidth 360

skinparam activity {
    BackgroundColor #FFFFFF
    BorderColor #9CA3AF
    FontColor #111827
    ArrowColor #6B7280
}

skinparam swimlane {
    BorderColor #9CA3AF
    TitleBackgroundColor #E5E7EB
}


|Nhân viên kho nhận|
start
:Lập yêu cầu điều chuyển hàng;
:Ghi rõ mặt hàng,\nsố lượng và kho xuất;


|Chủ cửa hàng|
:Tiếp nhận yêu cầu điều chuyển;
:Xem xét nhu cầu điều chuyển;

if (Yêu cầu điều chuyển được xác nhận?) then (Có)

else (Không)

    :Ghi nhận lý do\nkhông xác nhận;

    |Nhân viên kho nhận|
    :Tiếp nhận phản hồi;
    :Hủy yêu cầu điều chuyển;

    stop

endif


|Nhân viên kho xuất|
:Tiếp nhận yêu cầu điều chuyển;
:Kiểm tra hàng cần điều chuyển;

if (Đủ hàng để điều chuyển?) then (Có)

else (Không)

    :Ghi nhận số lượng\nkhông đáp ứng;

    |Nhân viên kho nhận|
    :Tiếp nhận thông tin thiếu hàng;
    :Điều chỉnh hoặc hủy\nyêu cầu điều chuyển;

    stop

endif


|Nhân viên kho xuất|
:Chuẩn bị hàng cần điều chuyển;
:Kiểm đếm hàng xuất;
:Kiểm tra mã hàng, lô,\nmàu và tình trạng hàng;
:Bàn giao hàng điều chuyển;


|Nhân viên giao hàng|
:Tiếp nhận hàng;
:Kiểm tra số lượng hàng bàn giao;
:Vận chuyển hàng đến kho nhận;
:Bàn giao hàng;


|Nhân viên kho nhận|
:Tiếp nhận hàng điều chuyển;
:Kiểm đếm số lượng thực nhận;

if (Hàng nhận đúng và đủ?) then (Có)

    :Nhập hàng vào kho;
    :Xác nhận hoàn tất điều chuyển;

else (Không)

    :Ghi nhận chênh lệch\nhoặc hàng không đạt;
    :Thông báo kết quả\ncho Chủ cửa hàng;

    |Chủ cửa hàng|
    :Xem xét chênh lệch điều chuyển;
    :Xác nhận phương án xử lý;

    |Nhân viên kho xuất|
    :Kiểm tra lại hàng đã xuất;
    :Phối hợp xử lý chênh lệch;

    |Nhân viên giao hàng|
    :Đối chiếu hàng đã nhận\nvà đã bàn giao;

    |Nhân viên kho nhận|
    :Xác nhận số lượng\nthực nhận cuối cùng;
    :Nhập số lượng được chấp nhận\nvào kho;
    :Xác nhận hoàn tất điều chuyển;

endif

stop

@enduml

@startuml BP04_Customer_Return

title BP-04 - Quy trình Khách hàng Trả hàng

scale 2000 width

!pragma useVerticalIf on

skinparam backgroundColor #FFFFFF
skinparam defaultFontName Arial
skinparam defaultFontSize 14
skinparam shadowing false
skinparam roundcorner 8
skinparam wrapWidth 250
skinparam swimlaneWidth 320

skinparam activity {
    BackgroundColor #FFFFFF
    BorderColor #9CA3AF
    FontColor #111827
    ArrowColor #6B7280
}

skinparam swimlane {
    BorderColor #9CA3AF
    TitleBackgroundColor #E5E7EB
}

|Khách hàng|
start
:Yêu cầu trả hàng;

|Nhân viên bán hàng|
:Tiếp nhận yêu cầu trả hàng;
:Xác nhận thông tin đơn bán;
:Thông báo điều kiện\nvà quy trình trả hàng;

|Khách hàng|
if (Khách hàng xác nhận trả hàng?) then (Có)

    :Bàn giao hàng cần trả;

else (Không)

    :Hủy yêu cầu trả hàng;
    stop

endif


|Nhân viên kho|
:Tiếp nhận hàng trả;
:Kiểm đếm và kiểm tra hàng;

if (Hàng trả đủ điều kiện tiếp nhận?) then (Có)

    :Nhập lại hàng vào kho;
    :Xác nhận số lượng hàng nhận lại;

else (Không)

    :Ghi nhận hàng không đạt\nhoặc số lượng không phù hợp;
    :Xác nhận số lượng\nđược chấp nhận nhận lại;

endif


|Kế toán|
:Tiếp nhận kết quả trả hàng;
:Điều chỉnh chứng từ bán hàng;
:Xác định số tiền hoàn trả;


|Thu ngân|
:Tiếp nhận thông tin hoàn tiền;
:Thực hiện hoàn tiền\ncho khách hàng;


|Khách hàng|
:Nhận tiền hoàn;
:Xác nhận hoàn tất trả hàng;

stop

@enduml

@startuml BP05_Supplier_Return

title BP-05 - Quy trình Trả hàng Nhà cung cấp

scale 2000 width

!pragma useVerticalIf on

skinparam backgroundColor #FFFFFF
skinparam defaultFontName Arial
skinparam defaultFontSize 14
skinparam shadowing false
skinparam roundcorner 8
skinparam wrapWidth 250
skinparam swimlaneWidth 340

skinparam activity {
    BackgroundColor #FFFFFF
    BorderColor #9CA3AF
    FontColor #111827
    ArrowColor #6B7280
}

skinparam swimlane {
    BorderColor #9CA3AF
    TitleBackgroundColor #E5E7EB
}


|Nhân viên kho|
start
:Xác định hàng cần trả\nnhà cung cấp;
:Ghi nhận số lượng hàng cần trả;
:Gửi thông tin trả hàng;


|Kế toán|
:Tiếp nhận thông tin hàng trả;
:Đối chiếu đơn mua\nvà chứng từ;
:Liên hệ nhà cung cấp;


while (Chưa thống nhất phương án trả hàng?) is (Có)

    |Nhà cung cấp|
    :Trao đổi điều kiện\nvà phương án nhận lại hàng;

    |Kế toán|
    :Xem xét phương án;
    :Trao đổi lại số lượng,\nthời gian hoặc cách thức trả;

endwhile (Không)


|Kế toán|
:Xác nhận phương án trả hàng;


|Nhân viên kho|
:Chuẩn bị hàng trả;
:Kiểm đếm hàng;


while (Số lượng hàng trả chưa khớp?) is (Có)

    :Kiểm tra lại hàng cần trả;
    :Điều chỉnh số lượng\nhàng chuẩn bị trả;
    :Kiểm đếm lại;

endwhile (Không)


|Nhân viên kho|
:Bàn giao hàng trả;


|Nhân viên giao hàng|
:Tiếp nhận hàng;
:Kiểm tra số lượng được bàn giao;
:Vận chuyển đến nhà cung cấp;
:Bàn giao hàng;


|Nhà cung cấp|
:Tiếp nhận hàng trả;
:Kiểm đếm số lượng nhận lại;


while (Hàng nhận lại chưa khớp?) is (Có)

    :Ghi nhận chênh lệch\nhàng nhận lại;

    |Nhân viên giao hàng|
    :Đối chiếu số lượng\nđã vận chuyển và bàn giao;

    |Nhân viên kho|
    :Đối chiếu số lượng\nđã xuất trả;

    |Kế toán|
    :Trao đổi kết quả đối chiếu\nvới nhà cung cấp;

    |Nhà cung cấp|
    :Kiểm tra lại số lượng\nthực tế nhận lại;

endwhile (Không)


|Nhà cung cấp|
:Xác nhận số lượng nhận lại;
:Phát hành chứng từ điều chỉnh;


|Kế toán|
:Tiếp nhận chứng từ điều chỉnh;
:Đối chiếu công nợ;


while (Chứng từ chưa khớp hàng trả?) is (Có)

    :Xác định nội dung chênh lệch;
    :Yêu cầu nhà cung cấp\nđiều chỉnh chứng từ;

    |Nhà cung cấp|
    :Điều chỉnh chứng từ;
    :Gửi lại chứng từ;

    |Kế toán|
    :Tiếp nhận chứng từ mới;
    :Đối chiếu lại công nợ;

endwhile (Không)


|Kế toán|
:Điều chỉnh giá trị mua hàng;

stop

@enduml

@startuml BP06_Stock_Count_Adjustment

title BP-06 - Quy trình Kiểm kê và Điều chỉnh tồn kho

scale 2000 width

!pragma useVerticalIf on

skinparam backgroundColor #FFFFFF
skinparam defaultFontName Arial
skinparam defaultFontSize 14
skinparam shadowing false
skinparam roundcorner 8
skinparam wrapWidth 250
skinparam swimlaneWidth 380

skinparam activity {
    BackgroundColor #FFFFFF
    BorderColor #9CA3AF
    FontColor #111827
    ArrowColor #6B7280
}

skinparam swimlane {
    BorderColor #9CA3AF
    TitleBackgroundColor #E5E7EB
}


|Kế toán|
start
:Lập kế hoạch kiểm kê;
:Xác định phạm vi kiểm kê;
:Thông báo thực hiện kiểm kê;


|Nhân viên kho|
:Chuẩn bị khu vực kiểm kê;
:Kiểm đếm hàng hóa thực tế;
:Ghi nhận kết quả kiểm kê;


while (Kết quả kiểm đếm chưa rõ ràng?) is (Có)

    :Kiểm tra lại vị trí,\nlô và hàng hóa;
    :Thực hiện kiểm đếm lại;
    :Cập nhật kết quả kiểm kê;

endwhile (Không)


|Nhân viên kho|
:Tổng hợp số lượng thực tế;


|Kế toán|
:Tiếp nhận kết quả kiểm kê;
:Đối chiếu số liệu;


while (Còn chênh lệch chưa xác định?) is (Có)

    :Xác định mặt hàng\nvà số lượng chênh lệch;

    |Nhân viên kho|
    :Kiểm tra lại hàng hóa,\nlô và vị trí lưu kho;
    :Kiểm đếm lại hàng chênh lệch;
    :Gửi kết quả kiểm tra lại;

    |Kế toán|
    :Tiếp nhận kết quả kiểm tra;
    :Đối chiếu lại số liệu;

endwhile (Không)


|Kế toán|
:Lập biên bản kiểm kê;


if (Có chênh lệch tồn kho?) then (Có)

    :Xác định số lượng\ncần điều chỉnh;
    :Ghi nhận điều chỉnh tồn kho;
    :Ghi nhận giá trị chênh lệch;
    :Hoàn tất kỳ kiểm kê;

    stop

else (Không)

    :Xác nhận tồn kho\nkhớp kết quả kiểm kê;
    :Hoàn tất kỳ kiểm kê;

    stop

endif

@enduml

@startuml BP01_Procurement_Inbound_Detailed

title BP-01 - Quy trình Mua hàng và Nhập kho

scale 2400 width

!pragma useVerticalIf on

skinparam backgroundColor #FFFFFF
skinparam defaultFontName Arial
skinparam defaultFontSize 14
skinparam shadowing false
skinparam roundcorner 8

skinparam wrapWidth 320
skinparam swimlaneWidth 480

skinparam activity {
    BackgroundColor #FFFFFF
    BorderColor #9CA3AF
    FontColor #111827
    ArrowColor #6B7280
}

skinparam swimlane {
    BorderColor #9CA3AF
    TitleBackgroundColor #E5E7EB
}


|Nhân viên kho|
start
:Kiểm tra tình hình tồn kho;


|Kế toán|
:Xác định hàng hóa\ncần bổ sung;
:Lập đề xuất mua hàng;


|Chủ cửa hàng|
:Tiếp nhận đề xuất mua hàng;
:Xem xét và phê duyệt;


while (Đề xuất chưa được phê duyệt?) is (Có)

    |Kế toán|
    :Tiếp nhận lý do\nchưa được phê duyệt;
    :Điều chỉnh mặt hàng,\nsố lượng hoặc nhu cầu mua;
    :Gửi lại đề xuất mua hàng;

    |Chủ cửa hàng|
    :Tiếp nhận đề xuất\nđã điều chỉnh;
    :Xem xét và phê duyệt lại;

endwhile (Không)


|Kế toán|
:Lập đơn mua hàng;
:Đặt hàng với nhà cung cấp;


|Nhà cung cấp|
:Tiếp nhận đơn đặt hàng;
:Kiểm tra khả năng cung ứng;


while (Chưa đáp ứng đầy đủ đơn hàng?) is (Có)

    :Thông báo khả năng cung ứng;
    :Đề xuất điều chỉnh số lượng,\nmặt hàng hoặc thời gian giao;

    |Kế toán|
    :Tiếp nhận phương án cung ứng;
    :Trao đổi với nhà cung cấp;
    :Điều chỉnh nội dung đơn mua;

    |Nhà cung cấp|
    :Tiếp nhận nội dung điều chỉnh;
    :Kiểm tra lại khả năng cung ứng;

endwhile (Không)


|Nhà cung cấp|
:Xác nhận đơn đặt hàng;
:Chuẩn bị hàng;
:Chuẩn bị chứng từ giao hàng;
:Giao hàng và chứng từ;


|Nhân viên kho|
:Tiếp nhận hàng;
:Kiểm đếm hàng thực tế;
:Kiểm tra mã hàng, lô, màu,\nquy cách và tình trạng hàng;


while (Hàng chưa đúng hoặc chưa đủ?) is (Có)

    :Ghi nhận số lượng chênh lệch,\nhàng sai hoặc hàng không đạt;
    :Thông báo kết quả kiểm nhận\ncho Kế toán;

    |Kế toán|
    :Tiếp nhận thông tin chênh lệch;
    :Đối chiếu với đơn mua;
    :Trao đổi phương án xử lý\nvới nhà cung cấp;

    |Nhà cung cấp|
    :Tiếp nhận thông tin chênh lệch;
    :Xác định phương án xử lý;
    :Thực hiện giao bổ sung,\nđổi hàng hoặc thu hồi hàng;

    |Nhân viên kho|
    :Tiếp nhận kết quả xử lý;
    :Kiểm đếm và kiểm tra lại\nhàng hóa;

endwhile (Không)


|Nhân viên kho|
:Nhập hàng vào kho;
:Sắp xếp hàng theo lô\nvà vị trí lưu trữ;
:Xác nhận kết quả nhận hàng;


|Kế toán|
:Tiếp nhận chứng từ mua hàng;
:Đối chiếu hàng nhận\nvà chứng từ;


while (Chứng từ chưa khớp\nvới hàng thực nhận?) is (Có)

    :Xác định nội dung\nchênh lệch chứng từ;
    :Trao đổi và yêu cầu\nđiều chỉnh chứng từ;

    |Nhà cung cấp|
    :Tiếp nhận yêu cầu điều chỉnh;
    :Điều chỉnh chứng từ;
    :Gửi lại chứng từ điều chỉnh;

    |Kế toán|
    :Tiếp nhận chứng từ mới;
    :Đối chiếu lại với\nhàng thực nhận;

endwhile (Không)


|Kế toán|
:Ghi nhận công nợ /\nthanh toán;

stop

@enduml
